const maxLength = 60000;
const translatedText = $('OpenAI Translate to Russian').item.json.message.content;
const chunks = [];

if (translatedText.length <= maxLength) {
  chunks.push(translatedText);
} else {
  let start = 0;
  while (start < translatedText.length) {
    let end = start + maxLength;
    if (end < translatedText.length) {
      const lastPeriod = translatedText.lastIndexOf('.', end);
      const lastNewline = translatedText.lastIndexOf('\n', end);
      end = Math.max(lastPeriod, lastNewline);
      if (end <= start) end = start + maxLength;
    }
    chunks.push(translatedText.substring(start, end));
    start = end;
  }
}

return chunks.map((chunk, index) => ({
  json: {
    chunk: chunk,
    chunkIndex: index,
    totalChunks: chunks.length,
    announcement: $('OpenAI Generate Announcement').item.json.message.content,
    summary: $('OpenAI Generate Summary').item.json.message.content,
    originalLink: $('RSS Feed Trigger').item.json.link,
    title: $('RSS Feed Trigger').item.json.title
  }
}));

const content = $json.chunk;
const paragraphs = content.split('\n').filter(p => p.trim().length > 0);
const telegraphContent = paragraphs.map(p => ({
  tag: 'p',
  children: [p.trim()]
}));

return {
  json: {
    ...($input.item.json),
    telegraphContent: JSON.stringify(telegraphContent)
  }
};

const gpt4oInputTokens = $('OpenAI Translate to Russian').item.json.usage?.prompt_tokens || 0;
const gpt4oOutputTokens = $('OpenAI Translate to Russian').item.json.usage?.completion_tokens || 0;

const garbageFilterInputTokens = $('OpenAI Garbage Filter').item.json.usage?.prompt_tokens || 0;
const garbageFilterOutputTokens = $('OpenAI Garbage Filter').item.json.usage?.completion_tokens || 0;

const announcementInputTokens = $('OpenAI Generate Announcement').item.json.usage?.prompt_tokens || 0;
const announcementOutputTokens = $('OpenAI Generate Announcement').item.json.usage?.completion_tokens || 0;

const summaryInputTokens = $('OpenAI Generate Summary').item.json.usage?.prompt_tokens || 0;
const summaryOutputTokens = $('OpenAI Generate Summary').item.json.usage?.completion_tokens || 0;

const gpt4oCostInput = (gpt4oInputTokens / 1000000) * 2.50;
const gpt4oCostOutput = (gpt4oOutputTokens / 1000000) * 10.00;
const gpt4oCost = gpt4oCostInput + gpt4oCostOutput;

const gpt41nanoCostInput = ((garbageFilterInputTokens + announcementInputTokens + summaryInputTokens) / 1000000) * 0.10;
const gpt41nanoCostOutput = ((garbageFilterOutputTokens + announcementOutputTokens + summaryOutputTokens) / 1000000) * 0.40;
const gpt41nanoCost = gpt41nanoCostInput + gpt41nanoCostOutput;

const totalCost = gpt4oCost + gpt41nanoCost;

return {
  json: {
    ...($input.item.json),
    announcement: $('Code Split Text').item.json.announcement,
    summary: $('Code Split Text').item.json.summary,
    telegraphUrl: $json.result.url,
    costs: {
      gpt4o: `$${gpt4oCost.toFixed(6)}`,
      gpt41nano: `$${gpt41nanoCost.toFixed(6)}`,
      total: `$${totalCost.toFixed(6)}`
    },
    tokens: {
      gpt4o: { input: gpt4oInputTokens, output: gpt4oOutputTokens },
      gpt41nano: { input: garbageFilterInputTokens + announcementInputTokens + summaryInputTokens, output: garbageFilterOutputTokens + announcementOutputTokens + summaryOutputTokens }
    }
  }
};

